import Foundation
import SwiftUI

/// Home Presenter
/// Handles the presentation logic and coordinates between View, Interactor, and Wireframe
final class HomePresenter: ObservableObject {

    // MARK: - Published Properties (UI State)
    
    @Published var shows: [Show] = []
    @Published var isLoading: Bool = false
    @Published var errorMessage: String? = nil

    // MARK: - Private Properties
    
    private let interactor: HomeInteractorInterface
    private let wireframe: HomeWireframeInterface

    // MARK: - Initialization
    
    /// Initialize the presenter with its dependencies
    /// - Parameters:
    ///   - interactor: The interactor handling business logic
    ///   - wireframe: The wireframe handling navigation
    init(
        interactor: HomeInteractorInterface,
        wireframe: HomeWireframeInterface
    ) {
        self.interactor = interactor
        self.wireframe = wireframe
    }
}

// MARK: - Public Methods

extension HomePresenter {
    
    /// Load shows from the API
    func loadShows() {
        isLoading = true
        errorMessage = nil
        
        interactor.getShows { [weak self] result in
            DispatchQueue.main.async {
                self?.isLoading = false
                
                switch result {
                case .success(let shows):
                    self?.shows = shows
                case .failure(let error):
                    self?.errorMessage = error.localizedDescription
                }
            }
        }
    }
    
    /// Handle show selection
    /// - Parameter show: The selected show
    func selectShow(_ show: Show) {
        wireframe.navigateToShowDetails(id: show.id)
    }
    
    /// Log out the user
    func logout() {
        interactor.logout()
        wireframe.navigateToLogin()
    }
    
    /// Clear any existing error message
    func clearError() {
        errorMessage = nil
    }
}